void TrajectoryExtender::optimize_trajectory(
  TrajectoryPoints & traj_points, const TrajectoryOptimizerParams & params,
  TrajectoryOptimizerData & data)
{
  if (!params.use_trajectory_extender) {
    return;
  }
  // Note: This function adds the current ego state to a history trajectory. Note that it is ok to
  // call this function several times with the same ego state, since there is a check inside the
  // function to avoid adding the same state multiple times.
  trajectory_extender_utils::add_ego_state_to_trajectory(
    past_ego_state_trajectory_.points, data.current_odometry,
    extender_params_.nearest_dist_threshold_m,
    autoware_utils_math::deg2rad(extender_params_.nearest_yaw_threshold_deg),
    extender_params_.backward_trajectory_extension_m);
  trajectory_extender_utils::expand_trajectory_with_ego_history(
    traj_points, past_ego_state_trajectory_.points, data.current_odometry);
}

void add_ego_state_to_trajectory(
  TrajectoryPoints & traj_points, const Odometry & current_odometry,
  const double nearest_dist_threshold_m, const double nearest_yaw_threshold_rad,
  const double backward_trajectory_extension_m)
{
  TrajectoryPoint ego_state;
  ego_state.pose = current_odometry.pose.pose;
  ego_state.longitudinal_velocity_mps = static_cast<float>(current_odometry.twist.twist.linear.x);

  if (traj_points.empty()) {
    traj_points.push_back(ego_state);
    return;
  }
  const auto & last_point = traj_points.back();
  const auto ego_yaw_rad = tf2::getYaw(ego_state.pose.orientation);
  const auto last_point_yaw_rad = tf2::getYaw(last_point.pose.orientation);

  const auto yaw_diff =
    std::abs(autoware_utils_math::normalize_radian(ego_yaw_rad - last_point_yaw_rad));
  const auto distance = autoware_utils_geometry::calc_distance2d(last_point, ego_state);
  constexpr double epsilon{1e-2};
  constexpr double epsilon_rad{1e-2};
  const bool is_change_small = distance < epsilon && yaw_diff < epsilon_rad;
  if (is_change_small) {
    return;
  }

  const bool is_change_large =
    distance > nearest_dist_threshold_m || yaw_diff > nearest_yaw_threshold_rad;
  if (is_change_large) {
    traj_points = {ego_state};
    return;
  }

  traj_points.push_back(ego_state);

  size_t clip_idx = 0;
  double accumulated_length = 0.0;
  for (size_t i = traj_points.size() - 1; i > 0; i--) {
    accumulated_length +=
      autoware_utils_geometry::calc_distance2d(traj_points.at(i - 1), traj_points.at(i));
    if (accumulated_length > backward_trajectory_extension_m) {
      clip_idx = i;
      break;
    }
  }
  traj_points.erase(traj_points.begin(), traj_points.begin() + static_cast<int>(clip_idx));
}

inline double normalize_radian(const double rad, const double min_rad = -pi)
{
  const auto max_rad = min_rad + 2 * pi;

  const auto value = std::fmod(rad, 2 * pi);
  if (min_rad <= value && value < max_rad) {
    return value;
  }

  return value - std::copysign(2 * pi, value);
}

double calc_distance2d(const Point1 & point1, const Point2 & point2)
{
  const auto p1 = get_point(point1);
  const auto p2 = get_point(point2);
  return std::hypot(p1.x - p2.x, p1.y - p2.y);
}

geometry_msgs::msg::Point get_point(const T & p)
{
  return geometry_msgs::build<geometry_msgs::msg::Point>().x(p.x).y(p.y).z(p.z);
}

void expand_trajectory_with_ego_history(
  TrajectoryPoints & traj_points, const TrajectoryPoints & ego_history_points,
  const Odometry & current_odometry)
{
  if (ego_history_points.empty()) {
    return;
  }

  if (traj_points.empty()) {
    traj_points.insert(traj_points.begin(), ego_history_points.begin(), ego_history_points.end());
    return;
  }

  const auto first_ego_history_point = ego_history_points.front();
  const auto first_ego_trajectory_point = traj_points.front();
  const auto first_ego_trajectory_point_arc_length = autoware::motion_utils::calcSignedArcLength(
    ego_history_points, first_ego_history_point.pose.position,
    first_ego_trajectory_point.pose.position);

  const auto ego_position = current_odometry.pose.pose.position;
  const auto distance_ego_to_first_trajectory_point =
    autoware_utils_geometry::calc_distance2d(first_ego_trajectory_point, ego_position);

  std::for_each(ego_history_points.rbegin(), ego_history_points.rend(), [&](const auto & point) {
    const auto point_arc_length = autoware::motion_utils::calcSignedArcLength(
      ego_history_points, first_ego_history_point.pose.position, point.pose.position);

    const bool is_ahead_of_first_point = point_arc_length > first_ego_trajectory_point_arc_length;
    const bool is_closer_than_first_trajectory_point =
      autoware_utils_geometry::calc_distance2d(point, ego_position) <
      distance_ego_to_first_trajectory_point;
    const bool is_point_already_in_trajectory =
      std::any_of(traj_points.begin(), traj_points.end(), [&](const TrajectoryPoint & traj_point) {
        return autoware_utils_geometry::calc_distance2d(traj_point, point) < 1e-1;
      });
    if (
      is_ahead_of_first_point || is_point_already_in_trajectory ||
      is_closer_than_first_trajectory_point) {
      return;
    }

    traj_points.insert(traj_points.begin(), point);
    traj_points.front().longitudinal_velocity_mps =
      first_ego_trajectory_point.longitudinal_velocity_mps;
    traj_points.front().acceleration_mps2 = first_ego_trajectory_point.acceleration_mps2;
  });
}

double calcSignedArcLength(
  const T & points, const geometry_msgs::msg::Point & src_point,
  const geometry_msgs::msg::Point & dst_point)
{
  try {
    validateNonEmpty(points);
  } catch (const std::exception & e) {
    RCLCPP_DEBUG(get_logger(), "%s", e.what());
    return 0.0;
  }

  const size_t src_seg_idx = findNearestSegmentIndex(points, src_point);
  const size_t dst_seg_idx = findNearestSegmentIndex(points, dst_point);

  const double signed_length_on_traj = calcSignedArcLength(points, src_seg_idx, dst_seg_idx);
  const double signed_length_src_offset =
    calcLongitudinalOffsetToSegment(points, src_seg_idx, src_point);
  const double signed_length_dst_offset =
    calcLongitudinalOffsetToSegment(points, dst_seg_idx, dst_point);

  return signed_length_on_traj - signed_length_src_offset + signed_length_dst_offset;
}

size_t findNearestSegmentIndex(const T & points, const geometry_msgs::msg::Point & point)
{
  const size_t nearest_idx = findNearestIndex(points, point);

  if (nearest_idx == 0) {
    return 0;
  }
  if (nearest_idx == points.size() - 1) {
    return points.size() - 2;
  }

  const double signed_length = calcLongitudinalOffsetToSegment(points, nearest_idx, point);

  if (signed_length <= 0) {
    return nearest_idx - 1;
  }

  return nearest_idx;
}

[[nodiscard]] size_t findNearestIndex(const T & points, const geometry_msgs::msg::Point & point)
{
  validateNonEmpty(points);

  double min_dist = std::numeric_limits<double>::max();
  size_t min_idx = 0;

  for (size_t i = 0; i < points.size(); ++i) {
    const auto dist = autoware_utils_geometry::calc_squared_distance2d(points.at(i), point);
    if (dist < min_dist) {
      min_dist = dist;
      min_idx = i;
    }
  }
  return min_idx;
}

double calc_squared_distance2d(const Point1 & point1, const Point2 & point2)
{
  const auto p1 = get_point(point1);
  const auto p2 = get_point(point2);
  const auto dx = p1.x - p2.x;
  const auto dy = p1.y - p2.y;
  return dx * dx + dy * dy;
}

geometry_msgs::msg::Point get_point(const T & p)
{
  return geometry_msgs::build<geometry_msgs::msg::Point>().x(p.x).y(p.y).z(p.z);
}

double calcLongitudinalOffsetToSegment(
  const T & points, const size_t seg_idx, const geometry_msgs::msg::Point & p_target,
  const bool throw_exception = false)
{
  if (seg_idx >= points.size() - 1) {
    const std::string error_message(
      "[autoware_motion_utils] " + std::string(__func__) +
      ": Failed to calculate longitudinal offset because the given segment index is out of the "
      "points size.");
    autoware_utils_system::print_backtrace();
    if (throw_exception) {
      throw std::out_of_range(error_message);
    }
    RCLCPP_DEBUG(
      get_logger(),
      "%s Return NaN since no_throw option is enabled. The maintainer must check the code.",
      error_message.c_str());
    return std::nan("");
  }

  const auto overlap_removed_points = removeOverlapPoints(points, seg_idx);

  if (throw_exception) {
    validateNonEmpty(overlap_removed_points);
  } else {
    try {
      validateNonEmpty(overlap_removed_points);
    } catch (const std::exception & e) {
      RCLCPP_DEBUG(get_logger(), "%s", e.what());
      return std::nan("");
    }
  }

  if (seg_idx >= overlap_removed_points.size() - 1) {
    const std::string error_message(
      "[autoware_motion_utils] " + std::string(__func__) +
      ": Longitudinal offset calculation is not supported for the same points.");
    autoware_utils_system::print_backtrace();
    if (throw_exception) {
      throw std::runtime_error(error_message);
    }
    RCLCPP_DEBUG(
      get_logger(),
      "%s Return NaN since no_throw option is enabled. The maintainer must check the code.",
      error_message.c_str());
    return std::nan("");
  }

  const auto p_front = autoware_utils_geometry::get_point(overlap_removed_points.at(seg_idx));
  const auto p_back = autoware_utils_geometry::get_point(overlap_removed_points.at(seg_idx + 1));

  const Eigen::Vector3d segment_vec{p_back.x - p_front.x, p_back.y - p_front.y, 0};
  const Eigen::Vector3d target_vec{p_target.x - p_front.x, p_target.y - p_front.y, 0};

  return segment_vec.dot(target_vec) / segment_vec.norm();
}

[[nodiscard]] T removeOverlapPoints(const T & points, const size_t start_idx = 0)
{
  if (points.size() < start_idx + 1) {
    return points;
  }

  T dst;
  dst.reserve(points.size());

  for (size_t i = 0; i <= start_idx; ++i) {
    dst.push_back(points.at(i));
  }

  constexpr double eps = 1.0E-08;
  for (size_t i = start_idx + 1; i < points.size(); ++i) {
    const auto prev_p = autoware_utils_geometry::get_point(dst.back());
    const auto curr_p = autoware_utils_geometry::get_point(points.at(i));
    if (std::abs(prev_p.x - curr_p.x) < eps && std::abs(prev_p.y - curr_p.y) < eps) {
      continue;
    }
    dst.push_back(points.at(i));
  }

  return dst;
}

geometry_msgs::msg::Point get_point(const T & p)
{
  return geometry_msgs::build<geometry_msgs::msg::Point>().x(p.x).y(p.y).z(p.z);
}

double calcSignedArcLength(const T & points, const size_t src_idx, const size_t dst_idx)
{
  try {
    validateNonEmpty(points);
  } catch (const std::exception & e) {
    RCLCPP_DEBUG(get_logger(), "%s", e.what());
    return 0.0;
  }

  if (src_idx > dst_idx) {
    return -calcSignedArcLength(points, dst_idx, src_idx);
  }

  double dist_sum = 0.0;
  for (size_t i = src_idx; i < dst_idx; ++i) {
    dist_sum += autoware_utils_geometry::calc_distance2d(points.at(i), points.at(i + 1));
  }
  return dist_sum;
}

